function run(input, params, h) {
  const traders = String(params.traders).split(",").map(t => t.trim()).filter(t => t);
  const items = String(params.items).split(",").map(t => t.trim().toLowerCase()).filter(t => t);
  const fresh = () => {
    const have = {};
    traders.forEach((t, i) => { have[t] = {}; items.forEach((it, j) => { have[t][it] = i === j ? params.start : 0; }); });
    return { have: have, turn: 0, pending: null, passes: 0, trades: 0, over: false };
  };
  const m = input.memory || fresh();
  const have = m.have;
  const list = t => items.map(it => have[t][it] + " g " + it).join(", ");
  const standings = () => traders.map(t => t + " has " + list(t) + ".").join("\n");
  const total = () => traders.reduce((sum, t) => sum + items.reduce((n, it) => n + have[t][it], 0), 0);
  const others = t => traders.filter(x => x !== t).join(" or ");
  const base = x => { const w = String(x == null ? "" : x).trim().toLowerCase(); return w.slice(-1) === "s" ? w.slice(0, -1) : w; };
  const yourTurn = before => {
    const t = traders[m.turn % traders.length];
    const say = before + "\n\n" + (params.tell ? standings() + "\n\n" : "") + "Your turn, " + t + ". Offer one trade to " + others(t) + ", or pass.";
    return { ask: t, over: false, trades: m.trades, have: have, say: say, memory: m };
  };
  const close = before => {
    m.over = true;
    return { ask: "", over: true, trades: m.trades, have: have, say: before + " The market is closed.\n\n" + standings() + "\n\nAltogether there are " + total() + " g, the same as at the start.", memory: m };
  };
  if (!input.memory) {
    return yourTurn("The market is open! Everyone wants a trail mix with " + items.slice(0, -1).join(", ") + " and " + items[items.length - 1] + ".");
  }
  if (m.over) {
    return { pass: false, ask: "", over: true, say: "The market is closed.", memory: m };
  }
  const from = traders.find(t => t.toLowerCase() === String(input.from).toLowerCase()) || String(input.from);
  if (m.pending) {
    const p = m.pending;
    let yes = false;
    for (const word of h.words(input.text)) {
      h.tick();
      if (["yes", "deal", "accept", "agreed", "ok", "okay", "sure"].indexOf(word) >= 0) { yes = true; break; }
      if (["no", "nope", "decline", "not"].indexOf(word) >= 0) break;
    }
    m.pending = null;
    m.turn = m.turn + 1;
    if (yes) {
      have[p.from][p.giveWhat] -= p.give; have[p.partner][p.giveWhat] += p.give;
      have[p.partner][p.getWhat] -= p.get; have[p.from][p.getWhat] += p.get;
      m.trades = m.trades + 1; m.passes = 0;
      const deal = "Deal! " + p.from + " gave " + p.partner + " " + p.give + " g " + p.giveWhat + " for " + p.get + " g " + p.getWhat + ".";
      if (traders.every(t => items.every(it => have[t][it] > 0))) return close(deal + " Everyone has some of every ingredient.");
      return yourTurn(deal);
    }
    m.passes = 0;
    return yourTurn(p.partner + " said no to " + p.from + "'s offer.");
  }
  const d = input.data || {};
  const who = String(d.partner == null ? "" : d.partner).trim().toLowerCase();
  if (d.partner != null && (!who || who === "nobody" || who === "none" || who === "pass")) {
    m.turn = m.turn + 1; m.passes = m.passes + 1;
    if (m.passes >= traders.length) return close(from + " passes. Everyone passed, one after another.");
    return yourTurn(from + " passes.");
  }
  const partner = traders.find(t => t.toLowerCase() === who && t !== from);
  const giveWhat = items.find(it => base(it) === base(d.giveWhat)), getWhat = items.find(it => base(it) === base(d.getWhat));
  const give = Math.round(Number(d.give)), get = Math.round(Number(d.get));
  let problem = "";
  if (!partner) problem = "Who do you want to trade with? Say " + others(from) + ", or nobody to pass.";
  else if (!giveWhat || !getWhat || giveWhat === getWhat) problem = "Say what you give and what you want back: two different things from " + items.join(", ") + ".";
  else if (!(give > 0) || !(get > 0)) problem = "Say how many grams you give and how many you want back, more than 0 of each.";
  if (!problem && have[from][giveWhat] < give) problem = "You only have " + have[from][giveWhat] + " g " + giveWhat + ", so you can't give " + give + " g.";
  else if (!problem && have[partner][getWhat] < get) problem = partner + " only has " + have[partner][getWhat] + " g " + getWhat + ", so they can't give you " + get + " g.";
  if (problem) {
    return { pass: false, refused: true, ask: from, over: false, trades: m.trades, have: have, say: problem + " Offer a trade again, or pass.", memory: m };
  }
  m.pending = { from: from, partner: partner, give: give, giveWhat: giveWhat, get: get, getWhat: getWhat };
  return { ask: partner, over: false, offer: m.pending, trades: m.trades, have: have, say: from + " offers you " + give + " g " + giveWhat + " for " + get + " g of your " + getWhat + ". " + (params.tell ? "You have " + list(partner) + ". " : "") + "Start your reply with yes or no.", memory: m };
}
